module.render:
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const int = (v, d) => { const n = parseInt(v, 10); return Number.isFinite(n) ? n : d; };
const question = String(sections[0] || '').trim();
const answer = String(sections.length > 1 ? sections.slice(1).join('\n\n') : '').trim();
const tag = String(args.tag || '').trim().replace(/[^\w-]/g, '');
const total = Math.max(0, int(args.minutes, 1)) * 60 + Math.max(0, Math.min(59, int(args.seconds, 0)));
const size = { sm: 'sm', md: 'md', lg: 'lg', xl: 'xl' }[String(args.size || 'md').toLowerCase()] || 'md';
const step = Math.max(0, int(args.step, 1));
const layout = String(args.layout || 'side').toLowerCase() === 'stack' ? 'stack' : 'side';
const handout = String(args.handout || 'blank').toLowerCase();

// A bold lead runs into the first line, unless the text starts with a block.
const lead = (title, body) => {
  const t = String(title || '').trim();
  if (!t) return body;
  if (!body) return '**' + t + '**';
  return /^\s*([-*+]\s|\d+[.)]\s|\\\[|\$\$|\||<|#|>)/.test(body) ? '**' + t + '**\n\n' + body : '**' + t + '**: ' + body;
};
// A named place a cue can point at (#TAG-q) — the core @focus block, so a text
// check of the deck finds the name as well.
const named = (name, body) => (tag ? '<!-- @focus ' + tag + '-' + name + ' -->\n\n' + body + '\n\n<!-- @endfocus -->' : body);

// The timer: the same element @timer renders (its script runs it, finds the tag
// on this block's wrapper and answers cmd:TAG), hidden in print.
let timer = '';
if (total > 0) {
  const label = String(args.label || '').trim();
  const mm = String(Math.floor(total / 60)).padStart(2, '0');
  const ss = String(total % 60).padStart(2, '0');
  timer = '<span class="mdp-exr-timer"><span class="mdp-mod-timer mdp-interactive mdp-size-' + size + '" style="border-radius:0.5em;justify-content:center" data-seconds="' + total + '" data-autostart="false">'
    + (label ? '<span class="mdp-timer-label">' + esc(label) + '</span>' : '')
    + '<button class="mdp-timer-btn mdp-timer-start" type="button" title="Start / Pause">&#9654;</button>'
    + '<span class="mdp-timer-display" style="width:' + (mm.length + 3) + 'ch">' + mm + ':' + ss + '</span>'
    + '<button class="mdp-timer-btn mdp-timer-reset" type="button" title="Reset">&#8634;</button>'
    + '</span></span>';
}

let html = '\n\n<div class="mdp-mod-exercise mdp-exr-' + layout + (timer ? '' : ' mdp-exr-notimer') + '">\n';
html += '<div class="mdp-exr-q">\n\n' + named('q', lead(args.title, question)) + '\n\n</div>\n';
if (timer) html += '<div class="mdp-exr-t">' + timer + '</div>\n';
if (answer) {
  let a = named('a', lead(args.answertitle, answer));
  if (handout !== 'show') a = '<!-- @answer' + (handout === 'gone' ? ' space: none' : '') + ' -->\n\n' + a + '\n\n<!-- @endanswer -->';
  if (step > 0) a = '<!-- @build step: ' + step + ' -->\n\n' + a + '\n\n<!-- @endbuild -->';
  html += '\n' + a + '\n\n';
}
html += '</div>\n\n';
return html;
